/** MPU 2025: Técnico e Analista de Enfermagem (Tipo 1), FGV.
 * Questões e gabaritos DEFINITIVOS, sem anuladas, imagens necessárias, enunciados
 * dependentes de textos anteriores ou legislação institucional fora da matriz.
 */
const LOTES=[{"codigo":"mpu2025-analista-enfermagem","orgao":"Ministério Público da União — MPU","ano":2025,"cargo":"Analista do MPU — Enfermagem","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/a08-analista-do-mpu-enfermagema08-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/mpu-gabarito-definitivo.pdf","questoes":[{"numero":1,"disciplina":"Língua Portuguesa","assunto":"Interpretação de Textos","enunciado":"Leia o texto abaixo: “O problema em matéria de audição vem do fato de que o cérebro é um órgão muito rápido e que se pensa muito mais depressa do que se fala. Assim que escutamos uma pessoa, solicitamos ao cérebro que trabalhe muito mais lentamente em comparação com sua capacidade. Entretanto, não chegamos realmente a reduzir a velocidade do cérebro; enquanto registramos as palavras transmitidas pelo emissor, o cérebro continua a tratar as centenas de palavras e a fazer associações de ideias. Em outros termos, quando escutamos, nos resta algum tempo livre para pensar. É o emprego desse tempo livre que torna a escuta boa ou má”. Levando em consideração que o conteúdo temático do texto é de difícil acesso pelo leitor comum, o processo utilizado para tornar esse conteúdo mais claro foi:","alternativas":["indicar a estruturação do texto no início da leitura;","acrescentar exemplos práticos ao texto;","reformular as informações já dadas;","utilizar sinônimos mais comuns para termos difíceis;","repetir informações com os mesmos termos"],"correta":"C"},{"numero":2,"disciplina":"Língua Portuguesa","assunto":"Coesão e Coerência","enunciado":"Todas as frases abaixo contêm pleonasmos, ou seja, repetições desnecessárias de palavras, que foram modificadas na reescritura dessas frases. A frase em que o processo de reescrituração NÃO elimina o pleonasmo original é:","alternativas":["Tenho o desejo de rever de novo o filme O Protetor 2 / Tenho o desejo de ver de novo o filme O Protetor 2;","Segundo ele, ele crê que esse vocábulo é um neologismo / Ele crê que esse vocábulo é um neologismo;","Os alunos dessa turma mutuamente se ajudam / Os alunos dessa turma se ajudam;","Os exterminadores de insetos eliminaram completamente as pulgas dos cães / Os exter minadores eliminaram completamente as pulgas dos cães;","Analisaram a situação e depois, em seguida, propuseram soluções / Analisaram a situação; em seguida propuseram soluções"],"correta":"D"},{"numero":3,"disciplina":"Língua Portuguesa","assunto":"Coesão e Coerência","enunciado":"Observe a seguinte frase: “Ele ficou esgotado porque correu muito”. A maneira de reescrevê-la que modifica o seu sentido original é:","alternativas":["Se ele correu muito, ficou esgotado;","Ele sentiu-se esgotado por ter corrido muito;","Já que correu muito, sentiu-se esgotado;","Porque correu muito, ficou esgotado;","Seu esgotamento ocorreu por ter corrido muito"],"correta":"A"},{"numero":4,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"Todas as frases abaixo empregaram processos para evitar -se a repetição de termos idênticos. A frase em que o processo usado foi a utilização de um termo de sentido mais geral (hiperônimo) é:","alternativas":["Meus alunos estudaram bastante e, por isso, eles merecem uma recompensa;","Entrou na avenida batendo tambor, mas o instrumento não resistiu por muito tempo;","Arrumando os discos, decidi vender aqueles que eu não escuto mais;","O proprietário do imóvel reuniu os inquilinos e, após alguns minutos, esse grande orador nos convenceu do aumento;","Traga suas fotografias para que eu as possa ver; as minhas fotos eu mostro depois"],"correta":"B"},{"numero":8,"disciplina":"Língua Portuguesa","assunto":"Estrutura e Formação de Palavras","enunciado":"A definição de um vocábulo deve respeitar a natureza do vocábulo. Entre as definições abaixo, aquela que procede desse modo, tornando-se uma definição válida, é:","alternativas":["refutação: destruir por argumentos sólidos as afirmações de outrem;","molestar: quando se provoca violência a alguém;","indolente: deixar de trabalhar, ficar passivo;","sucintamente: expressar-se em poucas palavras;","correto: aquele que age com correção"],"correta":"E"},{"numero":9,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"Observe o seguinte texto: “Nem sempre os ditados populares dão aulas positivas; como dizia Millôr Fernandes, ‘Devagar se vai ao longe, mas quando se chega lá, não se encontra mais ninguém’”. Nesse texto, a citação tem a função de:","alternativas":["participar a descoberta de um texto que traz prazer;","fazer progredir culturalmente um texto;","dar a conhecer uma opinião diversa da do autor;","indicar algo que apoia a ideia do texto;","fornecer um exemplo típico do estilo de um autor"],"correta":"D"},{"numero":10,"disciplina":"Língua Portuguesa","assunto":"Tempos, Modos e Vozes Verbais","enunciado":"Observe a seguinte frase: “Dá-lhes o dinheiro necessário!”. A única frase abaixo em que houve uma forma adequada de apassivação dessa frase é:","alternativas":["Que lhes seja dado o dinheiro necessário;","Dá-se-lhes o dinheiro necessário;","O dinheiro necessário lhes será dado;","Tem-lhes dado o dinheiro necessário;","O dinheiro necessário lhes teria sido dado"],"correta":"B"},{"numero":11,"disciplina":"Língua Portuguesa","assunto":"Funções da Linguagem","enunciado":"Todas as frases abaixo mostram solicitações ou conselhos de forma direta ou indireta. A frase que mostra uma forma indireta é:","alternativas":["Você aceita uma sobremesa?","Proíbo você de continuar com essa história;","Aconselho a todos a leitura de Guimarães Rosa;","Eu te peço para comprares a casa;","Se seu pai venceu na vida, ele trabalhou muito!"],"correta":"E"},{"numero":12,"disciplina":"Língua Portuguesa","assunto":"Funções da Linguagem","enunciado":"Na frase “Infelizmente, meu amigo se esqueceu de dar o aviso da entrevista para o pobre Marcelo”, cruzam -se duas funções de linguagem, que são:","alternativas":["referencial e fática;","conativa e metalinguística;","metalinguística e referencial;","emotiva e conativa;","fática e emotiva"],"correta":"D"},{"numero":13,"disciplina":"Língua Portuguesa","assunto":"Tempos, Modos e Vozes Verbais","enunciado":"A frase abaixo que mostra uma forma verbal inaceitável em relação à norma culta da língua portuguesa é:","alternativas":["Se você requerer o diploma, ele lhe será dado;","Se você dispuser de dinheiro, tudo fica mais fácil;","Se você vir o filme, vai ficar contente;","Se você intervier na discussão, ela termina;","Se você dizer a verdade, será melhor para todos"],"correta":"E"},{"numero":14,"disciplina":"Língua Portuguesa","assunto":"Variação Linguística","enunciado":"Compare as duas frases abaixo: - Dê-me aquela caixa. - Me dá aquela caixa. A segunda frase mostra o seguinte efeito em relação à primeira:","alternativas":["atenuação do valor de formalidade;","ênfase na ideia de ordem;","supressão da polidez;","suavização da ideia de pedido;","realce da ideia de tempo presente"],"correta":"A"},{"numero":15,"disciplina":"Língua Portuguesa","assunto":"Regência Verbal e Nominal","enunciado":"Observe a seguinte frase: “Não cheguei a assistir o início do show no final de ano”. A frase abaixo em que o verbo “assistir” é empregado no mesmo sentido que mostra na frase acima é:","alternativas":["Não assiste a você o dever de estar presente;","O professor deve assistir a todos os alunos;","O avô sempre foi assistido por todos os netos;","Não se pode assistir parado a uma agressão dessas;","O médico lhe assistiu nos últimos momentos. Noções de Sustentabilidade"],"correta":"D"},{"numero":29,"disciplina":"Direito Administrativo","assunto":"Organização Administrativa","enunciado":"Uma determinada organização pública da área de saúde tem sua estrutura dividida por funções, contemplando, assim, um departamento de apoio administrativo, um departamento de ensino e pesquisa e um departamento de atenção à saúde. Esse tipo de departamentalização tem como vantagem e desvantagem, respectivamente:","alternativas":["facilitar o atendimento das necessidades do usuário em suas particularidades; gerar sobreposições;","obter maior proveito de especializações e economia de escala, mesmo diante de conflitos; reduzir a visão integral;","otimizar uso de recursos humanos, financeiros e materiais com prazos limitados; causar alta rotatividade em contratações temporárias;","permitir a instalação de unidades próximas aos usuários, matérias-primas e canais de escoamento; ocasionar duplicidades e aumentos de custos;","promover a descentralização e facilitar controles e inovação; apresentar custos administrativos elevados e baixa sinergia entre departamentos"],"correta":"B"},{"numero":36,"disciplina":"Direito Administrativo","assunto":"Agentes Públicos","enunciado":"O Poder Executivo Federal promoveu, de ofício, o deslocamento de cargo de provimento efetivo ocupado, no âmbito do quadro geral de pessoal, para outro órgão do mesmo Poder, com prévia apreciação do órgão central do Sistema de Pessoal Civil da Administração Federal (SIPEC). A medida foi adotada para ajustamento de lotação e da fo rça de trabalho às necessidades dos serviços. Nessa situação, é correto afirmar que ocorreu uma:","alternativas":["redistribuição;","remoção;","readaptação;","reversão;","substituição"],"correta":"A"},{"numero":37,"disciplina":"Direito Administrativo","assunto":"Atos Administrativos","enunciado":"A autoridade administrativa federal competente, no intuito de eliminar situação contenciosa na aplicação do direito público, resolveu celebrar compromisso com os interessados, observando as formalidades previstas na Lei de Introdução às Normas do Direito Brasileiro. A respeito do compromisso em questão, é correto afirmar que:","alternativas":["pode conferir desoneração permanente de dever ou condicionamento de direito reconhecidos por orientação geral;","deve prever com clareza as obrigações das partes, o prazo para seu cumprimento e as sanções aplicáveis em caso de descumprimento;","deve produzir automaticamente efeitos retroativos, por expressa determinação legal;","tem como pressuposto a existência de razões de relevante interesse particular ou geral;","exige a prévia realização de consulta pública, dispensada a oitiva do órgão jurídico"],"correta":"B"},{"numero":38,"disciplina":"Direito Administrativo","assunto":"Licitações e Contratos","enunciado":"Determinado órgão da Administração Pública promoveu licitação para a contratação de serviços de engenharia com vistas à reforma de sua sede. Na etapa de julgamento, duas propostas foram idênticas conforme os critérios previstos em edital. Dentre os critérios de desempate entre duas ou mais propostas adotados pela Lei Federal nº 14.133/2021, é correto apontar:","alternativas":["o desenvolvimento pelo licitante de programa de integridade, conforme orientações dos órgãos de controle;","a contratação, pelo licitante, de mulheres vítimas de violência doméstica;","a utilização, pelo licitante, de bens reciclados, recicláveis ou biodegradáveis;","a contratação, pelo licitante, de oriundos ou egressos do sistema prisional;","a utilização, pelo licitan te, de bens manufaturados e serviços originários de Estados Partes do Mercado Comum do Sul (Mercosul)"],"correta":"A"},{"numero":39,"disciplina":"Direito Administrativo","assunto":"Responsabilidade Civil do Estado","enunciado":"Adalgisa ajuizou ação de indenização por danos morais em face da concessionária de serviço público que realiza a coleta e o tratamento de esgoto em s ua cidade. Na inicial, Adalgisa afirmou morar nas redondezas de uma estação de tratamento de esgoto operada pela ré, que emitiria um mau odor causador de profunda violação à sua dignidade humana. Os elementos de prova produzidos ao longo do processo demonstraram que, de fato, a atividade exercida pela estação de tratamento de esgoto descumpria as normas de regência e causava a emissão de odores fétidos que atingiam a região em que residia Adalgisa, gerando nesta desconforto, frustração, desespero e problemas de saúde, principalmente respiratórios. Nessa situação, é possível afirmar que:","alternativas":["a responsabilidade da concessionária de serviço público por danos a terceiros exige a demonstração de dolo ou culpa, sendo possível a inversão do ônus da prova ope judicis;","a responsabilidade da concessionária de serviço público e do poder concedente é solidária, sendo facultado a Adalgisa exigir o pagamento de quaisquer deles na fase de cumprimento de sentença;","a responsabilidade civil da concessionária de serviço público é objetiva, não havendo necessidade de demonstração de culpa ou dolo de seus agentes;","a responsabilidade da concessionária de serviço público por danos a terceiros exige a demonstração de dolo ou culpa, assegurada a inversão do ônus da prova ope legis;","a responsabilidade civil da concessionária de serviço público é baseada na teoria do risco integral, não havendo necessidade de demonstração do nexo causal entre conduta e resultado danoso."],"correta":"C"},{"numero":40,"disciplina":"Direito Administrativo","assunto":"Agentes Públicos","enunciado":"Bertoldo, servidor públ ico federal, praticou conduta escandalosa na repartição e insubordinação grave em serviço, pois, instado pelo seu superior ao cumprimento de certa tarefa inserida nas suas atribuições, respondeu aos gritos que não iria obedecer a ordem, deu um soco no rost o de seu superior e atirou o monitor de seu computador contra a parede. Foi ajuizada ação penal em face de Bertoldo, no bojo da qual foi instaurado incidente de insanidade mental. Os laudos médicos constataram a enfermidade psíquica de Bertoldo, indicando que o acusado era, ao tempo da ação, inteiramente incapaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento. Com base nisso, o juízo criminal proferiu sentença absolutória imprópria, com imposição de medida de segurança. Nessa situação, é correto afirmar que, no processo administrativo disciplinar instaurado em desfavor de Bertoldo pelos mesmos fatos:","alternativas":["é possível a aplicação de pena de demissão, dado o caráter subjetivo das infrações disciplinares e a independência entre as instâncias criminal e administrativa;","é obrigatória a aplicação de pena de demissão, dado o caráter objetivo das infrações disciplinares e a independência entre as instâncias criminal e administrativa;","é obrigatória a aplicação de pena de suspensão, dado o caráter objetivo das infrações disciplinares e a independência entre as instâncias criminal e administrativa;","é possível a aplicação de pena de suspensão, dado o caráter subjetivo das infrações disciplinares e a independência entre as instâncias criminal e administrativa;","descabe a fixação de sanção administrativa, impondo -se à Administração Pública o dever de avaliar a eventual concessão de licença para tratamento de saúde ou de aposentadoria por invalidez."],"correta":"E"},{"numero":41,"disciplina":"Legislação do COFEN","assunto":"Código de Ética dos Profissionais de Enfermagem","enunciado":"Com base nas disposições do Código de Ética dos Profissionais de Enfermagem, considerando as sanções cabíveis e os direitos assegurados, é correto afirmar que:","alternativas":["é permitido ao profissional de enfermagem recusar -se a prestar assistência em situação de urgência e emergência, desde que apresente justificativa posterior ao Conselho Regional de Enfermagem;","a violação do sigilo profissional pelo enfermeiro, quando realizada com o consentimento do paciente, não configura infração ética e, portanto, não implica sanções administrativas;","o profissional de enfermagem pode ser suspenso pelo prazo máximo de 30 dias caso seja condenado por prática considerada infração ética de natureza grave, conforme deliberado pelo Conselho Regional de Enfermagem;","é direito do profissional de enfermagem recusar -se a executar atividades que não sejam de sua competência técnica, científica, ética e legal ou que não ofereçam segurança ao profissional, à pessoa, à família e à coletividade;","o descumprimento de normas estabelecidas por autoridades sanitárias configura infração passível de aplicação de advertência confidencial pelo Conselho Federal de Enfermagem, independentemente da gravidade do ato"],"correta":"D"},{"numero":42,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"No contexto da admini stração em enfermagem, um dos grandes desafios dos gestores é alinhar a gestão estratégica aos cuidados de enfermagem para garantir eficiência, qualidade e segurança. Nesse sentido, considerando os conceitos e ferramentas de planejamento, organização e controle, é correto afirmar que:","alternativas":["na elaboração de um plano estratégico para o setor, o enfermeiro gestor deve priorizar a alocação de recursos humanos para atender à demanda de pacientes, com base na taxa de ocupação hospitalar do ano anterior;","a padr onização dos processos e protocolos de enfermagem dentro da organização permite a manutenção de um fluxo contínuo de trabalho, descartando a necessidade de ajustes periódicos;","a implementação de uma auditoria interna para avaliar os protocolos assistenciais, associada a feedbacks periódicos aos profissionais de enfermagem, descreve uma prática administrativa que integra função de controle e função de direção;","a avaliação do desempenho da equipe de enfermagem é mais efetiva quando realizada com base em indicadores quantitativos, uma vez que os indicadores qualitativos e de satisfação não refletem de forma objetiva esse tipo de avaliação;","a matriz SWOT é a ferramenta mais adequada para identificar as forças e fraquezas dos processos assistenciais n o ambiente interno, porém não é tão eficiente para identificação das ameaças e oportunidades relacionadas ao ambiente externo"],"correta":"C"},{"numero":44,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"A avaliação de desempenho é uma ferramenta de gestão essencial para analisar a performance dos profissionais e promover o desenvolvimento individual e organizacional. Considerando as principais ferramentas de avaliação de desempenho, é correto afirmar que:","alternativas":["a avaliação 360° é um método de autoavaliação no qual os colaboradores devem analisar seu desempenho, identificando pontos fortes e pontos para melhorar;","o ciclo PDCA modificado tem sido utilizado como ferramenta para avaliação do desempenho de equipes e pode ser aplicado principalmente em cenários desafiadores;","a avaliação por competências baseia -se na análise das competências técnicas e comportamentais exigidas para o cargo, considerando três dimensões: conhecimentos, habilidades e atitudes;","a avaliação por resultados não é eficaz na gestão de desempenho, pois ignora fatores qualitativos e subjetivos que influenciam o desempenho dos colaboradores;","a avaliação baseada em indicadores de desempenho permite um diagnóstico detalhado do desempenho do enfermeiro e da equipe, identificando lacunas no conhecimento ou na execução de tarefas"],"correta":"C"},{"numero":45,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"A a uditoria de enfermagem é uma ferramenta de gestão essencial para avaliar, monitorar e melhorar a qualidade da assistência prestada, alinhando as práticas da equipe às políticas institucionais e às necessidades do paciente. No que se refere aos aspectos rel acionados à auditoria de enfermagem, analise as afirmativas a seguir, considerando V para a(s) verdadeira(s) e F para a(s) falsa(s). ( ) A auditoria concorrente tem caráter essencialmente preventivo e consiste em uma análise prévia e minuciosa que procura detectar situações de alarme para evitar problemas no futuro. ( ) A implantação de auditorias sistemáticas, envolvendo, entre outras coisas, a análise de indicadores de desempenho e a revisão de prontuários, é fundamental para identificar e corrigir fragilidades no processo assistencial. ( ) A auditoria operacional concentra -se na análise dos custos envolvidos na assistência, com ênfase na eficiência financeira, sem ter como foco principal a conformidade dos processos assistenciais ou a qualidade d os cuidados prestados pela equipe. A sequência correta é:","alternativas":["F – F – F;","V – F – V;","F – F – V;","V – V – V;","F – V – F"],"correta":"E"},{"numero":46,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"A avaliação da qualidade nos processos de trabalho é uma prática essencial para assegurar a excelência na assistência à saúde e promover a melhoria contínua. Envolve a aplicação de conceitos e ferramentas que consideram indicadores de desempenho, satisfação dos usuários e conformidade com padrões estabelecidos. Considerando as principais ferramentas de avaliação da qualidade, é correto afirmar que:","alternativas":["o diagrama de Pareto auxilia na priorização de problemas ao identificar quais fatores são mais relevantes dentro de um processo, conforme sua frequência e impacto;","o ciclo PDCA é uma ferramenta que deve ser utiliza da apenas para corrigir problemas já identificados, sem aplicação na melhoria contínua dos processos;","o histograma é uma ferramenta qualitativa utilizada para analisar opiniões e percepções dos profissionais sobre a qualidade dos processos;","o fluxograma é um método utilizado para representar dados estatísticos por meio de gráficos de dispersão, facilitando a análise de correlação entre variáveis;","o diagrama de Ishikawa, também conhecido como espinha de peixe, é utilizado para classificar as prin cipais causas de um problema, mostrando o percentual de importância de cada uma"],"correta":"A"},{"numero":47,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"Foi demandada a um determinado serviço de saúde a implementação de novos processos de trabalho com o objetivo de otimizar recursos e melhorar a qualidade e a eficiência do s serviços prestados. Para isso, a gestão da unidade fez um levantamento das melhores práticas do mercado por meio de benchmarking funcional. Esse método visa a realizar comparações:","alternativas":["entre concorrentes específicos de um produto ou funções de interesse;","com funções similares, em empresas diferentes, para identificar estratégias e processos eficientes;","por meio da parceria entre duas empresas, visando à troca de experiências;","de processos ou funções semelhantes de forma genérica, mesmo em empresas de segmentos diferentes;","entre setores da própria organização para analisar níveis de produtividade e demais indicadores."],"correta":"B"},{"numero":48,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Os indicadores de saúde são fundamentais para compreender o desempenho de sistemas de saúde, as condições de vi da da população e os determinantes que influenciam esses cenários, sendo ferramentas importantes para auxiliar a gestão na tomada de decisão. Acerca dos indicadores de saúde, é correto afirmar que:","alternativas":["a proporção de idosos na população é um indicador que está associado ao aumento da expectativa de vida e das taxas de fecundidade e de natalidade;","a taxa de fecundidade total é definida como a razão entre os componentes etários extremos da população, representados por idosos e jovens;","a esperança de v ida ao nascer é o número médio de anos de vida esperados para um recém -nascido, mantido o padrão de mortalidade existente na população residente;","a taxa de mortalidade infantil diz respeito ao número de óbitos de menores de 5 anos de idade em relação a os nascidos vivos;","o óbito materno diz respeito às mortes ocorridas durante a gestação ou até 42 dias após o seu término, desde que o tempo de gestação tenha sido igual ou maior que 38 semanas"],"correta":"C"},{"numero":49,"disciplina":"Enfermagem","assunto":"Gestão em Enfermagem","enunciado":"Um gestor de saúde utilizou o Balanced Scorecard (BSC) como metodologia de gestão estratégica para avaliar e melhorar o desempenho das unidades de saúde. Considerando a função e a utilidade dessa ferramenta, é correto afirmar que:","alternativas":["o BSC é uma ferramenta eficaz para a gestão estratégica de unidades de saúde, pois permite alinhar objetivos organizacionais com indicadores de desempenho;","para implementar o BSC em uma unidade de saúde, basta adotar os indicadores tradicionais da área hospitalar, pois a metodologia não exige adaptação ao conte xto específico da instituição;","o BSC é mais adequado para organizações que operam com fins lucrativos, pois sua estrutura de medição de desempenho depende essencialmente de métricas financeiras;","a adoção do BSC em unidades de saúde elimina a necessidade de monitoramento contínuo, pois a definição de indicadores estratégicos garante a estabilidade da gestão;","o BSC, ao enfatizar múltiplas perspectivas, dificulta a gestão de unidades de saúde, pois exige a mensuração de fatores subjetivos que impos sibilitam o monitoramento adequado dos resultados organizacionais"],"correta":"A"},{"numero":50,"disciplina":"Direito Administrativo","assunto":"Licitações e Contratos","enunciado":"A enfermeira de um órgão público, que faz parte do Núcleo de Planejamento de Contratos responsável pela elaboração de projetos para a aquisição de materiais e insumos de saúde, deu início a um processo licitatório para a aquisição de medicamentos. Com base nas disposições normativas a esse respeito, é correto afirmar que:","alternativas":["por se tratar de aquisição de medicamentos, pode ser realizado por meio de inexigibilidade;","o termo de referê ncia faz parte da fase de divulgação do edital;","a licitação é dispensável para a aquisição de medicamentos destinados exclusivamente ao tratamento de doenças raras definidas pelo Ministério da Saúde;","a licitação deverá ser realizada preferencialmen te sob a forma presencial, admitida a utilização da forma eletrônica, desde que motivada;","o documento de formalização de demanda é dispensável nos processos de aquisição de medicamentos, pois trata -se de uma necessidade objetiva"],"correta":"C"},{"numero":51,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"O Programa Naciona l de Segurança do Paciente (PNSP) estabelece estratégias e ações para melhorar a segurança do paciente nos serviços de saúde. Nesse sentido, uma abordagem adequada para a implantação de um Plano de Segurança do Paciente em uma unidade de saúde de médio porte é:","alternativas":["realizar notificações obrigatórias apenas em casos de eventos adversos graves, deixando os eventos menores para resolução interna sem registro formal;","promover a comunicação efetiva entre os profissionais do serviço de saúde e estimular a participação do paciente e dos familiares na assistência prestada;","priorizar intervenções corretivas após a ocorrência de eventos adversos, considerando que a prevenção nem sempre é custo-efetiva em instituições menores;","conduzir audito rias de segurança nos setores de maior criticidade, visando a concentrar os esforços e minimizar recursos financeiros despendidos;","promover processos de capacitação em segurança do paciente, dando prioridade aos gestores e profissionais que atuam na vigilância dos eventos adversos"],"correta":"B"},{"numero":52,"disciplina":"Enfermagem","assunto":"Política Nacional de Humanização","enunciado":"Considere que uma unidade básica de saúde (UBS) deseja implementar ações para melhorar a experiência dos usuários e trabalhadores do SUS. Nesse caso, com base na Política Nacional de Humanização (PNH), a forma mais adequa da para promover o cuidado baseado em uma política humanizada e eficiente é:","alternativas":["reduzir o tempo médio das consultas para aumentar o número de atendimentos;","incentivar a criação de espaços de cogestão, com a participação de profissionais, gestores e usuários na tomada de decisões;","instituir um fluxo rígido e padronizado de atendimento, minimizando a possibilidade de conflitos entre usuários e profissionais;","implementar processos de acolhimento e triagem com foco na hora de chegada e na redução do tempo de atendimento;","promover sistemas de escuta qualificada com foco nos trabalhadores de saúde."],"correta":"B"},{"numero":53,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Um profissional de saúde sofreu um acidente de trabalho com potencial exposição ao HIV. Foram tomadas todas as medidas cabíveis, incl uindo a realização de testes rápidos e início da profilaxia pós-exposição (PEP) com antirretroviral (ARV). Nesse caso, acerca da PEP e da repetição dos testes, é correto afirmar que:","alternativas":["nos casos em que o atendimento ocorrer após 72 horas da exposição, a PEP deve ser administrada com o acréscimo de dolutegravir ao esquema principal de ARV;","quando indicada a PEP, o esquema preferencial antirretroviral deverá ser estruturado com comprimidos de tenofovir e lamivudina;","a profilaxia pós-exposição com antirretroviral tem duração de 28 dias, devendo ser repetida após 15 dias de pausa e repetição dos testes;","todas as pessoas potencialmente expostas ao HIV devem repetir testagem em 30 dias após a exposição, caso não tenham completado a profilaxia com ARV;","todas as pessoas potencialmente expostas ao HIV devem repetir testagem em 30 dias após a exposição, mesmo depois de completada a profilaxia com ARV"],"correta":"E"},{"numero":54,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Durante o exame físico do aparelho respiratório de um paciente adulto com queixa de dispneia e tosse produtiva, o enfermeiro observou sinais clínicos que demandam avaliação detalhada. Acerca das técnicas de ausculta, percussão e palpação no exame físico desse paciente, é correto afirmar que:","alternativas":["durante a ausculta pulmonar, a presença de roncos difusos e sibilos em um paciente com dispneia e tosse produtiva sugere obstrução das vias aéreas associada ao acúmulo de secreções;","na percussão pulmonar, a hiper -ressonância em hemitórax esquerdo em um paciente com dispneia e tosse produtiva é um achado específico de pneumotórax;","durante a palpação torácica, a presença de frêmito toracovocal aumentado em um paciente com dispneia e tosse produtiva é um achado específico de pneumonia lobar;","na ausculta pulmonar, a presença de estertores cr epitantes bilaterais em bases pulmonares em um paciente com dispneia e tosse produtiva é um achado específico de edema pulmonar cardiogênico;","na percussão pulmonar, a macicez em hemitórax direito associada à diminuição do frêmito tátil é um achado específico de derrame pleural"],"correta":"A"},{"numero":55,"disciplina":"Enfermagem","assunto":"Gerenciamento de Resíduos de Serviços de Saúde (GRSS)","enunciado":"No que se refere ao Regulamento de Boas Práticas de Gerenciamento dos Resíduos de Serviços de Saúde (RSS), analise as afirmativas a seguir, considerando V para a(s) verdadeira(s) e F para a(s) falsa(s). ( ) Os sacos para a condicionamento de RSS do Grupo A devem ser substituídos ao atingirem o limite de 2/3 de sua capacidade ou então a cada 48 horas, independentemente do volume. ( ) A sala de utilidades ou expurgo pode ser compartilhada para o armazenamento temporário dos RSS dos Grupos A, D e E, devendo ser compatível com a área a ser ocupada pelos coletores em uso. ( ) Peças anatômicas, como placentas, devem ser segregadas e acondicionadas em saco vermelho duplo, como barreira de proteção, e contidas em recipiente ex clusivo devidamente identificado. A sequência correta é:","alternativas":["V – V – F;","F – V – F;","V – V – V;","F – F – F;","V – F – V"],"correta":"A"},{"numero":56,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Na prática assistencial, as precauções para prevenção e controle de infecções são estratégias fundamentais para reduzir a transmissão de patógenos. Nesse caso, considerando as precauções por formas de transmissão, é correto afirmar que:","alternativas":["as precauções para gotículas visam a prevenir a transmissão de microrganismos por via respiratória por partículas menores que 5 µm (micra) de pacientes com doença transmissível, geradas pela tosse, pelo espirro e durante a fala;","as precauções por contato são indicadas para evitar a transmissão de agentes infecciosos, incluindo microrganismos de importância epidemiológica, que s e espalham por contato direto ou indireto, como em doenças como meningite e influenza;","a precaução padrão é indicada para paciente com suspeita de infecção transmitida por contato, gotículas e aerossóis, devendo ser substituída por precaução específica quando houver a confirmação do diagnóstico;","os pacientes com infecções transmitidas por aerossóis, como é o caso da tuberculose, podem ser internados com outros pacientes com infecção pelo mesmo microrganismo , com exceção dos pacientes com suspeita de tuberculose resistente ao tratamento;","em casos de infecções transmitidas por gotículas, o uso de máscara cirúrgica pelo paciente e pelo profissional de saúde, associado a precauções gerais, é suficiente para prevenir a transmissão em um ambiente compartilhado."],"correta":"D"},{"numero":57,"disciplina":"Enfermagem","assunto":"Centro de Material e Esterilização (CME)","enunciado":"Considerando os processos de esterilização de produtos para saúde e suas indicações na prática assistencial, é correto afirmar que:","alternativas":["a esterilização por óxido de etileno é amplamente utilizada para produtos sensíveis ao calor, como disposi tivos eletrônicos e plásticos, sendo um procedimento seguro e com baixo risco de toxicidade;","para dispositivos de uso único, a radiação gama proporciona resultados semelhantes em um menor tempo de exposição e sem risco de toxicidade;","a esterilizaçã o por peróxido de hidrogênio a baixa temperatura deve ser evitada para o tratamento de instrumentos que possuam altos teores de matéria orgânica, pois podem interferir na eficácia do processo;","a esterilização por calor úmido (autoclave) é segura para u ma gama ampla de instrumentos médicos; entretanto, sua eficiência pode ser reduzida se os tempos de exposição forem excessivamente prolongados, já que pode ocorrer a oxidação de metais e o comprometimento de partes plásticas;","o ácido peracético é segur o no processamento de metais não tratados e plásticos ou borrachas com baixa resistência química"],"correta":"C"},{"numero":58,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Na coleta de amostras de trato respiratório para o diagnóstico laboratorial da influenza, deve -se maximizar a colheita de células epiteliais infectadas pe lo vírus. A esse respeito, analise as afirmativas a seguir, considerando V para a(s) verdadeira(s) e F para a(s) falsa(s). ( ) Aspirados nasofaríngeos (ANF) têm um maior teor celular e são superiores aos swabs nasofaríngeos e orofaríngeos (SNF) no que concerne ao isolamento do vírus influenza. ( ) As amostras de secreção respiratória devem ser mantidas em temperatura adequada de refrigeração (4 °C a 8 °C) e encaminhadas aos Laboratórios Centrais de Saúde Pública, preferencialmente no mesmo dia da coleta. ( ) Para pacientes que evoluíram a óbito, deverá ser realizada a coleta de amostras para o diagnóstico viral e histopatológico exclusivamente do tecido das tonsilas e da mucosa nasal. A sequência correta é:","alternativas":["V – V – F;","F – V – V;","V – V – V.","F – F – F;","V – F – V"],"correta":"A"},{"numero":60,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Durante a avaliação de um paciente, foi observada a presença de tiragem intercostal. Acerca desse achado, é correto afirmar que:","alternativas":["a tiragem é um fenômeno fisiológico, caracterizado por expansão excessiva dos espaços intercostais durante a inspiração;","a tiragem é mais visível na face posterior do tórax e ocorre devido ao aumento da pressão positiva na cavidade pleural durante a inspiração;","nas retrações unilaterais, as causas estão sempre relacionadas a alterações na parede torácica, sem envolvimento da árvore brônquica;","a tiragem é decorrente de um aumento da pressão negativa intratorácica durante a inspiração, sendo observada em condições de obstrução das vias aéreas ou esforço respiratório intenso;","a extensão e a intensidade da tiragem dependem exclusivamente da força dos músculos respiratórios, independentemente de fatores como obstru ção das vias aéreas"],"correta":"D"},{"numero":61,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Foi realizado um levantamento epidemiológico em uma cidade com 100.000 habitantes para investigar a ocorrência de uma determinada doença. No início do levantamento, 2.000 pessoas já tinham o diagnóstico da doença. Durante um ano de acompanhamento, 500 novos casos foram identificados e 200 pessoas morreram. Com base nesses dados, é correto afirmar que:","alternativas":["a incidência da doença no início do levantamento foi de 2%;","a prevalência da doença no início do levantamento foi de 10%;","a taxa de mortalidade da doença durante o ano foi de 10%;","a prevalência da doença durante o ano foi menor que a incidência;","a incidência da doença durante o levantamento foi de 500 casos"],"correta":"E"},{"numero":63,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um paciente internado na clínica médica de um hospital apresentou sinais e sintomas característicos da tríade de Beck. Essa tríade, que indica uma emergência clínica, é composta por:","alternativas":["hipoglicemia, hiperpneia e taquiarritmia;","bradicardia, hipertensão arterial e bradipneia;","icterícia, dor abdominal e febre com calafrios;","hipotensão, hipofenose de bulhas e turgência de jugular;","estase sanguínea, lesão endotelial e hipercoagulabilidade."],"correta":"D"},{"numero":64,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Na assistência a um paciente adulto, 30 anos, 75 quilos, vítima de queimadura por chama no braço direito e em toda a extensão anterior do tórax, a reposição volêmica recomendada com ringer com lactato para as primeiras 24 horas é equivalente a:","alternativas":["3.037 ml;","4.050 ml;","5.062 ml;","6.075 ml;","8.100 ml"],"correta":"B"},{"numero":65,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um paciente do sexo masculino, 58 anos, chegou ao serviço de emergência com queixa de dor torácica intensa, irradiada para o braço esquerdo e acompanhada de náuseas, inici ada há mais ou menos 5 horas. Durante o atendimento, suspeitou -se de infarto agudo do miocárdio (IAM) e foram solicitados exames laboratoriais, incluindo a dosagem de biomarcadores cardíacos, com elevação de alguns deles. Acerca desses biomarcadores, é correto afirmar que:","alternativas":["a CK-MB é considerada a principal enzima para o diagnóstico precoce de infarto, uma vez que sua elevação ocorre nas primeiras 2 horas após o início dos sintomas;","a troponina T é o marcador ideal para o diagnóstico de infarto, pois apresenta elevação precoce e volta ao normal rapidamente, permitindo avaliar a extensão do dano miocárdico em poucas horas;","devido à sua rápida elevação nas primeiras horas, alta sensibilidade e alto valor preditivo negativo, a mioglobina é considerada excelente para descartar o diagnóstico de IAM;","a troponina I é útil como marcador de infarto agudo do miocárdio, mas sua especificidade é limitada devido à sua lenta elevação e presença em outras condições musculares e renais;","a CK -MM é um dos marcadores mais específicos para diagnóstico de infarto agudo do miocárdio, pois sua elevação é observada nas primeiras 4 horas após o início dos sintomas, sendo capaz de diferenciar o IAM de outras condições cardíacas"],"correta":"C"},{"numero":66,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Uma paciente adulta, 25 anos, in ternada em uma unidade de saúde para tratamento de colecistite aguda, apresentou dor abdominal insidiosa com piora progressiva em hipocôndrio direito, acompanhada de sinais sistêmicos como febre, náuseas e vômitos. Após exame clínico e laboratorial, suspei tou-se de abdômen agudo. O quadro clínico apresentado e as características da dor são sugestivos de abdômen:","alternativas":["obstrutivo;","agudo vascular;","agudo perfurativo;","agudo inflamatório;","agudo hemorrágico"],"correta":"D"},{"numero":67,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Paciente adulta, 32 anos, na 28ª sema na de gestação, tem sinais e sintomas moderados de covid -19. Nesse caso, o Ministério da Saúde orienta a utilização do Escore de Alerta Obstétrico Modificado (MEOWS) como ferramenta de apoio na tomada de decisão. Com base nesse escore, a alternativa que co rresponde a parâmetros do alerta amarelo é:","alternativas":["Temperatura = 39 °C e FR = 18 rpm;","FR = 22 rpm e PA sistólica = 95 mmHg;","FC = 90 bpm e PA diastólica = 89 mmHg;","PA diastólica = 110 mmHg e FC = 90 bpm;","SatO2 = 96% e alteração no nível de consciência"],"correta":"B"},{"numero":68,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Um paciente adulto com histórico de dependência química deu entrada na unidade de saúde com sinais e sintomas característicos de intoxicação por cocaína, entre os quais agitação, taquicardia, hipertensão, hipertermia e diaforese. O antídoto recomendado para reverter a taquicardia provocada por essa intoxicação é:","alternativas":["naloxona;","glucagon;","flumazenil;","gluconato de cálcio;","bicarbonato de sódio"],"correta":"E"},{"numero":69,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Na assistência a um paciente adulto em tratamento de transtorno esquizoafetivo, a e quipe de enfermagem deve estar atenta a sinais e sintomas que indiquem a necessidade de interrupção do tratamento. O sintoma que indica a interrupção do tratamento com clorpromazina é:","alternativas":["dislipidemia;","hipercinesia;","taquicardia;","distonia significativa;","hipotensão ortostática"],"correta":"D"},{"numero":71,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Um paciente com histórico de infarto agudo do miocárdio foi submetido a uma cintilografia de perfusão miocárdica. Acerca desse exame, é correto afirmar que a cint ilografia do miocárdio:","alternativas":["é um exame invasivo que requer a inserção de cateteres nas artérias coronárias para avaliar o fluxo sanguíneo;","é contraindicada para pacientes com asma, devido ao risco de broncospasmo induzido pelos radiofármacos utilizados;","é capaz de fornecer informações anatômicas detalhadas sobre as artérias coronárias, permitindo a visualização direta de obstruções;","é indicada para avaliar a presença de isquemia miocárdica em pacientes com dor torácica e múltiplos fatores de ris co cardiovascular;","não pode ser realizada por pacientes com marca -passo definitivo, pois o dispositivo interfere na captação das imagens"],"correta":"D"},{"numero":72,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Durante a assistência a um paciente queimado, o enfermeiro identificou sinais de infecção nas lesões. A alternativa que corresponde a um desses sinais é:","alternativas":["aumento da quantidade de exsudato seroso em queimaduras de segundo grau;","descolamento precoce da escara seca e transformação em escara úmida;","presença de escaras necróticas e formação de crostas em queimaduras de terceiro grau;","dor intensa e constante, sem alívio com analgésicos, em queimaduras de segundo grau;","borda eritematosa bem definida e presença de exsudato claro e espesso ao redor da queimadura"],"correta":"B"},{"numero":73,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"Na fase de expansão (rápida) do trata mento da desidratação grave de uma criança de 5 anos, o esquema recomendado de reidratação endovenosa é a administração de s oro fisiológico a 0,9% ou ringer com lactato no seguinte volume e tempo:","alternativas":["10 ml/kg em 10 minutos;","20 ml/kg em 15 minutos;","30 ml/kg em 30 minutos;","50 ml/kg em 60 minutos;","70 ml/kg em 120 minutos"],"correta":"C"},{"numero":74,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"De acordo com proposta do Ministério da Saúde para estratificação do risco de hemorragia pós -parto (HPP), um dos fatores que indica risco moderado é:","alternativas":["placenta prévia;","pré-eclâmpsia grave;","três partos vaginais prévios;","uso de anticoagulantes;","histórico de atonia uterina"],"correta":"E"},{"numero":75,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um paciente adulto, internado em uma unidade de pronto atendimento, apresenta choque séptico refratário à reposiçã o volêmica. Foi prescrito um agente vasoativo com o objetivo de manter a PAM >= 65 mmHg. Sobre a administração desse medicamento, é correto afirmar que:","alternativas":["a administração de vasopressores deve ser feita preferencialmente por via periférica, pois essa via reduz o risco de complicações, como necrose tecidual;","a dopamina é a droga vasoativa de primeira escolha para o choque séptico, pois tem efeito predominantemente vasodilatador e melhora a perfusão renal sem causar efeitos adversos significativos;","os vasopressores devem ser administrados preferencialmente por acesso venoso central para evitar complicações, como necrose tecidual em caso de extravasamento;","o uso de vasopressores, como noradrenalina e vasopressina, está indicado em todos os casos de choque hipovolêmico, pois promove aumento do débito cardíaco independentemente da reposição volêmica;","os efeitos adversos dos vasopressores são limitados e incluem principalmente hipotensão postural transitória e bradicardia compensatória"],"correta":"C"},{"numero":76,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Os agravos à saúde relacionados ao trabalho são condições que podem ser desencadeadas ou agravadas pelas atividades laborais, exigindo notificação e manejo adequado pelos serviços de saúde. Considerando os protocolos do Ministério da Saúde e do Ministério do Trabalho, é correto afirmar que:","alternativas":["as lesões por esforço repetitivo (LER) e os distúrbios osteomusculares relacionados ao trabalho (DORT) são agravos comuns e de notificação compulsória em todo o território nacional, independentemente do nexo causal estabelecido;","as intoxicações ocupacionais por agrotóxicos são de notificação compulsória no Sistema de Informação de Agravos de Notificação (SINAN), e o manejo inclui identificação precoce dos sintomas, afastamento da exposição e uso de antídotos específicos quando disponíveis;","o transtorno mental relacionado ao trabalho, como a síndrome de Burnout, não está contemplado na lista de doenças relacionadas ao trabalho (LDRT) do Ministério da Saúde, pois não há evidências científicas suficientes para caracterizar o nexo causal;","a perda auditiva induzida por ruído ocupacional (PAIR) é um agravo irreversível, porém pode ser prevenido exclusivamente por meio do uso de equipamentos de proteção individual (EPIs), sem necessidade de medidas administrativas ou de controle ambiental;","a radiação ionizante utilizada em atividades ocupacionais, como saúde e indústrias, não representa risco significativo à saúde desde que os trabalhadores usem dosímetros de forma adequada, independentemente da dose acumulada ao l ongo dos anos."],"correta":"B"},{"numero":77,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"A evolução da gripe (influenza) geralmente tem resolução espontânea em sete dias, embora a tosse, o mal -estar e a fadiga possam permanecer por algumas semanas. Alguns casos, no entanto, podem evoluir com complicações. Nesse sentido, um paciente idoso, internado para tratamento de influenza, apresentou manifestações clínicas que indicam complicações da doença. Entre os sintomas que caracterizam essas manifestações, estão:","alternativas":["bronquite e febre;","miosite e pneumonia;","sinusite e otite média;","rabdomiólise e crupe;","parotidite e miocardite"],"correta":"B"},{"numero":78,"disciplina":"Enfermagem","assunto":"Tuberculose","enunciado":"Acerca das estratégias de busca ativa de sintomáticos respiratórios e de rastreamento da tuberculose, é correto afirmar que:","alternativas":["a estratégia de busca ativa pode incluir a realização de exames diagnósticos em populações de maior risco, como pessoas privadas de liberdade, indígenas e indivíduos em situação de rua, independentemente da presença de sintomas;","a busca ativa de casos deve ser realizada apenas em contatos domiciliares de pacien tes com tuberculose bacilífera, pois o risco de transmissão em ambientes extrafamiliares é considerado insignificante;","o rastreamento de tuberculose deve ser realizado exclusivamente em indivíduos sintomáticos respiratórios com tosse por mais de três s emanas, uma vez que casos assintomáticos não têm relevância epidemiológica na transmissão da doença;","o exame de escarro deve ser solicitado apenas em indivíduos que apresentem perda de peso e febre persistente, uma vez que a tosse isolada não é suficie nte para suspeição de tuberculose;","a busca ativa deve ser interrompida em locais onde há baixa incidência da doença, pois a probabilidade de encontrar casos novos nesses contextos é mínima e não justifica a aplicação de recursos"],"correta":"A"},{"numero":79,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um paciente de 68 anos, com histórico de diabetes mellitus tipo 2 e hipertensão arterial, é admitido no pronto -socorro com febre (39,2 °C), taquicardia (FC = 120 bpm), hipotensão (PA = 85/50 mmHg) e confusão mental. O exame físico revela pele quente e hiperemiada. Foi iniciado o protocolo de sepse com base nos critérios de síndrome da resposta inflamatória sistêmica (SIRS) e disfunções orgânicas apresentadas pelo paciente. Entre os critérios que caracterizam a disfunção orgânica, está:","alternativas":["PA sistólica < 95 mmhg;","temperatura axilar > 38 °C;","débito urinário < 0,5 ml/kg/h;","frequência cardíaca > 90 bpm;","frequência respiratória > 20 rpm"],"correta":"C"},{"numero":80,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"Em 2024 foram incluídas na Lista Nacional de Notificação Compulsória de doenças, agravos e eventos de saúde pública doenças como câncer relacionado ao trabalho, de rmatoses ocupacionais e distúrbios de voz relacionados ao trabalho. Acerca da notificação dessas doenças e agravos, é correto afirmar que:","alternativas":["a notificação compulsória de dermatoses ocupacionais é obrigatória apenas quando há confirmação laboratorial da doença;","o câncer relacionado ao trabalho deve ser notificado mediante exposição comprovada a agentes carcinogênicos em laudos periciais;","distúrbios de voz relacionados ao trabalho são de notificação compulsória apenas para profissionais da educação e comunicação;","a notificação de doenças ocupacionais deve ser feita exclusivamente por meio de formulários físicos entregues diretamente à vigilância epidemiológica municipal;","a notificação compulsória de doenças relacionadas ao trabalho deve ser realizada por qualquer profissional de saúde, independentemente de sua categoria profissional. RASCUNHO PROVA DISCURSIVA O futuro do planeta Terra está se voltando para os demais planetas do sistema solar. Um assessor do novo presidente americano diz ter a intenção de chegar a Marte em pouco tempo, preocupação que tam bém mostra a China. Ocorre, porém, que essas conquistas custam milhões e milhões de dólares, que poderiam ser empregados para a solução de problemas terrenos. Afinal de contas, as conquist as espaciais são um bom investimento, ou não? Que ganho poderíamos ter com elas? Diga o que pensa a respeito do tema, elaborando um texto dissertativo -argumentativo, em linguagem culta, com no mínimo 20 e no máximo 30 linhas. Valor: 40 pontos. 1 5 10 15 20 25 30 Ministério Público da União FGV Conhecimento A08 - Analista do MPU - Enfermagem Tipo 1 – Branca Ministério Público da União FGV Conhecimento A08 - Analista do MPU - Enfermagem Tipo 1 – Branca Ministério Público da União FGV Conhecimento A8 - Analista do MPU - Enfermagem Tipo 1 – Branca"],"correta":"E"}]},{"codigo":"mpu2025-tecnico-enfermagem","orgao":"Ministério Público da União — MPU","ano":2025,"cargo":"Técnico do MPU — Enfermagem","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/t02-tecnico-do-mpu-enfermagemt02-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/mpu-gabarito-definitivo.pdf","questoes":[{"numero":4,"disciplina":"Língua Portuguesa","assunto":"Classes de Palavras","enunciado":"A frase em que a palavra “bem” se classifica, quanto ao significado, como em “Torna -se possível, enfim, em face das variedades geográficas e culturais, fixar duas regiões bem definidas...”, é:","alternativas":["Bem, eu não tenho a mesma opinião sobre esse tema;","O lugar já esteve pior, mas agora está bem;","Nunca me senti tão bem quanto agora;","Faça o bem sem olhar a quem;","As festas no evento foram bem-organizadas. Texto 2 Expressão oral e escrita Tem-se discutido muito sobre as funções essenciais da linguag em humana e a hierarquia natural que há entre elas. É fácil observar, por exemplo, que é pelo uso da linguagem falando oralmente ao próximo ou mentalmente a nós mesmos, que conseguimos organizar o nosso pensamento e torná-lo articulado, concatenado e nítido; é assim que, nas crianças, a partir do momento em que, rigorosamente, adquirem o manejo da língua dos adultos e deixam para trás o balbucio e a expressão fragmentada e difusa, surge um novo vigor de raciocínio, que não só decorre do desenvolvimento do c érebro, mas também da circunstância de que o indivíduo dispõe agora da língua materna, a serviço de todo o seu trabalho de atividade mental. Se se inicia e desenvolve o estudo metódico dos caracteres desse novo e precioso instrumento, vai, concomitantement e, aperfeiçoando -se a capacidade de pensar, da mesma sorte que se aperfeiçoa o operário com o domínio e o conhecimento seguro das ferramentas da sua profissão. (Mattoso Câmara)"],"correta":"E"},{"numero":7,"disciplina":"Língua Portuguesa","assunto":"Semântica e Significação","enunciado":"“...surge um novo vigor de raci ocínio, que não só decorre do desenvolvimento do cérebro, mas também da circunstância de que o indivíduo dispõe agora da língua materna, a serviço de todo o seu trabalho de atividade mental.” Nesse segmento do texto 2, o termo “agora”:","alternativas":["está mal -empregado por não se referir a nenhum termo anterior do texto;","se refere a um momento citado anteriormente;","se liga ao momento presente da leitura do texto;","se prende ao momento de vida profissional;","se conecta com a ocasião da produção do texto."],"correta":"B"},{"numero":8,"disciplina":"Língua Portuguesa","assunto":"Coesão e Coerência","enunciado":"“Se se inicia e desenvolve o estudo metódico dos caracteres desse novo e precioso instrumento, vai, concomitantemente, aperfeiçoando-se a capacidade de pensar, da mesma sorte que se aperfeiçoa o operário com o domínio e o conhecimento seguro das ferramentas da sua profissão.” Na defesa de sua ideia, o autor do texto 2 apela para:","alternativas":["o testemunho de autoridade dos estudiosos;","uma narrativa de tema semelhante;","uma analogia entre atividades;","a opinião do próprio autor do texto;","conhecimentos biológicos estabelecidos"],"correta":"C"},{"numero":10,"disciplina":"Língua Portuguesa","assunto":"Pontuação","enunciado":"O segmento textual abaixo em que falta uma vírgula é:","alternativas":["Tem-se discutido muito sobre as funções essenciais da linguagem humana e a hierarquia natural que há entre elas;","É fácil observar, por exemplo, que é pelo uso da linguagem falando oralmente ao próximo ou mentalmente a nós mesmos, que conseguimos organizar o nosso pensamento e torná-lo articulado, concatenado e nítido;","é assim que, nas crianças, a partir do mom ento em que, rigorosamente, adquirem o manejo da língua dos adultos e deixam para trás o balbucio e a expressão fragmentada e difusa, surge um novo vigor de raciocínio;","que não só decorre do desenvolvimento do cérebro, mas também da circunstância de qu e o indivíduo dispõe agora da língua materna, a serviço de todo o seu trabalho de atividade mental;","Se se inicia e desenvolve o estudo metódico dos caracteres desse novo e precioso instrumento, vai, concomitantemente, aperfeiçoando-se a capacidade de pensar. Texto 3 Método científico Certamente a ciência se iniciou num tempo muito anterior ao registro histórico e ao das artes das cavernas. Talvez tenha nascido com o Homem, com as primeiras formas de magia tribal, resultantes das perplexidades dos primitivos diante dos fenômenos naturais e suas forças. Daí não só surgiram os embriões das religiões primitivas, como também as fontes dos conhecimentos, das experiências acumuladas pelo homem através dos séculos. Os detentores destes co nhecimentos, os feiticeiros, poderiam ser comparados a sacerdotes e, mais ainda, a cientistas primitivos que, no seu empirismo, através de seus ritos mágicos, procuravam “recriar”, ou então, amenizar os fenômenos naturais. No momento em que o homem se deu conta de que as mágicas não mereciam muita confiança, que ora davam certo, ora não, no momento em que percebeu que outros fatores, não mágicos, atuavam nos fenômenos, um importante passo foi dado. (Paulo Quintanilha Nobre de Mello)"],"correta":"B"},{"numero":12,"disciplina":"Língua Portuguesa","assunto":"Sintaxe da Oração e do Período","enunciado":"“Certamente a ciência se iniciou num tempo muito anterior ao registro histórico e ao das artes das cavernas.” Sobre esse segmento inicial do texto 3, é correto afirmar que:","alternativas":["o termo “certamente” marca alta probabilidade e baixo grau de dúvida;","a forma verbal “se iniciou” seria corretamente grafada “iniciou-se”;","a frase está estruturada na voz passiva pronominal;","a expressão “num tempo” ganha precisão cronológica com os termos que a seguem;","o segmento inicial tem caráter objetivamente informativo"],"correta":"B"},{"numero":13,"disciplina":"Língua Portuguesa","assunto":"Coesão e Coerência","enunciado":"“Daí não só surgiram os embriões das religiões primitivas, como também as fontes dos conhecimentos, das experiências acumuladas pelo homem através dos séculos.” A frase abaixo em que a locução “através de” mostra o mesmo valor presente na frase acima do texto 3, é:","alternativas":["Os sons do filme passavam através da parede;","Através da leitura, tomamos conhecimento de tudo;","Os aviões passam através das nuvens;","Os trabalhos foram feitos através de meses;","Através de horas de estudo, chegamos ao alvo. Texto 4 Analfabetos Hoje considera-se que há dois tipos de analfabetos. O analfabeto específico que é o homem que não sabe ler nem escrever, e o analfabeto funcional, que é o homem que sabe ler e escrever, que pode até ter diver sos graus de educação e que, do ponto de vista cultural, é tão analfabeto, ou mais do que o outro; mais, digo eu, porque perdeu a cultura popular, de experiência, de costume tradicional etc., que o analfabeto da aldeia possui, e não adquiriu outra. (Jorge de Sena)"],"correta":"D"},{"numero":15,"disciplina":"Língua Portuguesa","assunto":"Tempos, Modos e Vozes Verbais","enunciado":"“Hoje considera-se que há dois tipos de analfabetos” (texto 4); uma outra forma de voz passiva dessa mesma frase é:","alternativas":["Hoje consideram-se a existência de dois tipos de analfabetos;","Hoje foi considerado que há dois tipos de analfabetos;","Hoje é considerada a existência de dois tipos de analfabetos;","É considerada, hoje, que há dois tipos de analfabetos;","Hoje era considerada a existência de dois tipos de analfabetos. Noções de Sustentabilidade"],"correta":"C"},{"numero":36,"disciplina":"Direito Administrativo","assunto":"Organização Administrativa","enunciado":"XYZ é uma entidade sem fins lucrativos, criada em virtude de autorização legislativa, para o desenvolvimento de atividades que não exijam execução por órgãos ou entidades de direito público, com autonomia administrativa, patrimônio próprio gerido pelo seu órgão de direção e funcionam ento custeado por recursos da União e de outras fontes. A relação jurídica mantida entre a XYZ e seus prestadores de serviço é regida pela Consolidação das Leis do Trabalho. Além disso, XYZ adquiriu personalidade jurídica com a inscrição da escritura públi ca de sua constituição no Registro Civil de Pessoas Jurídicas. É correto afirmar que XYZ é uma:","alternativas":["empresa pública;","fundação pública de direito público;","autarquia;","fundação pública de direito privado;","sociedade de economia mista"],"correta":"D"},{"numero":37,"disciplina":"Direito Administrativo","assunto":"Agentes Públicos","enunciado":"João, servidor público federal, havia sido aposentado por invalidez, mas uma junta médica oficial declarou insubsistentes os motivos da sua aposentadoria. João, então, retornou à atividade no mesmo cargo que ocupava. Nessa hipótese, é correto afirmar que ocorreu uma:","alternativas":["reintegração;","reversão;","recondução;","readaptação;","reforma"],"correta":"B"},{"numero":38,"disciplina":"Direito Administrativo","assunto":"Licitações e Contratos","enunciado":"Em determinado contrato administrativo de terceirização de serviço contínuo, passados 12 meses de sua vigência, a União e a contratada celebraram termo aditivo pa ra promover o reequilíbrio econômico -financeiro, com vistas à adequação ao preço de mercado. Para tanto, foi demonstrada, de forma analítica, a variação dos componentes dos custos do contrato, devidamente justificada. Nessa situação, é correto afirmar que ocorreu:","alternativas":["atualização financeira;","revisão;","repactuação;","reajuste;","correção monetária."],"correta":"C"},{"numero":39,"disciplina":"Direito Administrativo","assunto":"Organização Administrativa","enunciado":"No âmbito da Administração Pública federal, três entidades estabeleceram instância de natureza interinstitucional para atuar de forma compartilhada, com a finalidade de simplificar o processo administrativo mediante participação concomitante de todas as autoridades e agentes decisórios e dos responsáveis pela instrução técnico -jurídica, observada a natureza do objeto e a compatibilidade do procedimento e de sua formalização com a legislação pertinente. Nessa situação, é correto afirmar que ocorreu:","alternativas":["uma decisão coordenada;","um ato consultivo conjunto;","uma normativa multissetorial;","um julgamento sumaríssimo;","uma outorga voluntária"],"correta":"A"},{"numero":40,"disciplina":"Direito Administrativo","assunto":"Poderes Administrativos","enunciado":"Fiscais do Instituto Brasileiro do Meio Ambiente e dos Recursos Naturais Renováveis (Ibama) receberam notícia, devidamente circunstanciada, de que João, naquele momento, estava ateando fogo e provocando incêndio no interior de sua propriedad e rural e, assim, destruindo e danificando floresta, vegetação nativa e espécies nativas plantadas, objeto de especial preservação, sem qualquer autorização ou licença da autoridade ambiental competente, fato que, como se sabe, constitui infração administrativa ambiental. Ao comparecerem ao local, os fiscais comprovaram a veracidade da denúncia e adotaram as providências cabíveis. O Ibama instaurou auto de infração e aplicou a sanção administrativa de multa prevista na legislação de regência, em desfavor d e João, sem prejuízo das medidas regularmente adotadas na esfera ambiental. De acordo com a doutrina de Direito Administrativo, a regular aplicação da sanção administrativa de multa pelo Ibama a João decorreu diretamente do poder administrativo:","alternativas":["de polícia;","disciplinar;","hierárquico;","regulamentar;","de segurança ambiental."],"correta":"A"},{"numero":41,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"O cérebro é composto pelos hemisférios direito e esquerdo, cada um com quatro lados denominados de acordo com o osso próximo a eles e com funções distintas. São funções do lobo temporal:","alternativas":["conduta e comportamento emocional;","interpretação de sensações visuais e olfato;","funções intelectuais e memória armazenada;","atividade motora voluntária e atividade de personalidade;","memória de curto prazo e interpretação do paladar"],"correta":"E"},{"numero":42,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"O conjunto dos eventos cardíacos que ocorrem entre o início de um batimento e o início do próximo é denominado ciclo cardíaco. Sobre esses eventos, é correto afirmar que:","alternativas":["durante a fase de enchimento ventricular rápido, o fluxo de sangue ocorre passivamente para o interior dos ventrículos devido ao gradiente de pressão entre átrios e ventrículos. Essa fase é responsável pela maior parte do enchimento ventricular;","a sístole atrial ocorre imediatamente antes da ejeção ventricular, contribuindo para aproximadamente 70% do volume diastólico final dos ventrículos, e sua eficiência independe do funcionamento normal das válvulas AV;","na fase isovolumétrica da sístole ventricular, há fechamento das válvulas atrioventriculares e abertura simultânea das válvulas semilunares, com geração rápida da pressão necessária para a ejeção ventricular;","quando a pressão no interior do ventrículo esquerdo aumenta até pouco acima d e 80 mmHg, a pressão ventricular força a abertura das válvulas semilunares. Esse fenômeno é denominado curva de pressão aórtica;","a diástole é o período mais longo do ciclo cardíaco e é crucial para o enchimento ventricular. Durante esse período, as válvulas semilunares permanecem abertas para permitir a entrada de sangue nos ventrículos"],"correta":"A"},{"numero":43,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Considerando a anatomia do sistema digestivo, é correto afirmar que:","alternativas":["o esôfago é um tubo muscular localizado posteriormente à traqueia e anterior à coluna vertebral, apresentando camadas distintas como a adventícia, uma túnica serosa verdadeira em sua porção abdominal;","o estômago possui três camadas de músculo liso em sua parede muscular (longitudinal, circular e oblíqua). Essas camadas são encontradas u niformemente em todo o comprimento do órgão, desempenhando um papel crucial na mistura e propulsão do bolo alimentar;","o jejuno, parte média do intestino delgado, é caracterizado por pregas circulares mais numerosas e bem desenvolvidas do que o íleo, co ntribuindo para a maior absorção de nutrientes nessa porção;","o pâncreas é um órgão retroperitoneal dividido em cabeça, colo, corpo e cauda. Suas secreções exócrinas escoam pelos ductos pancreáticos principal e acessório, que drenam diretamente no íleo terminal para auxiliar na digestão;","o fígado, maior glândula do corpo, apresenta lóbulos hepáticos delimitados por tríades portais, que contêm ramos da artéria hepática, veia porta e ducto biliar. A veia central de cada lóbulo drena diretamente para as veias subclávias, completando o retorno venoso."],"correta":"A"},{"numero":44,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"No exame físico, as técnicas de inspeção, palpação, percussão e ausculta desempenham papéis fundamentais na identificação de alterações clínicas. Sobre essas técnicas, é correto afirmar que:","alternativas":["a inspeção estática avalia apenas características morfológicas do paciente, enquanto a inspeção dinâmica abrange a avaliação de movimentos, sendo realizada preferencialmente antes das outras etapas do exame físico para evitar interferências;","na percussão torác ica, um som timpânico é considerado normal sobre áreas pulmonares, indicando a presença adequada de ar nos alvéolos. A ausência desse som sugere patologia como pneumotórax ou enfisema;","na ausculta cardíaca, o segundo ruído cardíaco (B2) é sempre mais a udível no foco mitral, enquanto o primeiro ruído cardíaco (B1) é mais audível nos focos aórtico e pulmonar devido à proximidade anatômica com as válvulas correspondentes;","a percussão abdominal é realizada com o objetivo de identificar alterações no tim bre dos sons, sendo o som maciço indicativo de órgãos sólidos, enquanto a presença de som timpânico em toda a cavidade abdominal sugere normalidade;","durante o exame da ausculta pulmonar, o ruído broncovesicular deve ser ouvido sobre as bases pulmonares , e sua presença em áreas não correspondentes pode ser fisiológica em indivíduos jovens e fisicamente ativos"],"correta":"D"},{"numero":45,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Na prática assistencial, a aplicação da semiologia e semiotécnica é essencial para a avaliação do paciente. Sobre a abordagem prática em difer entes situações clínicas, é correto afirmar que:","alternativas":["a avaliação do estado de hidratação é feita preferencialmente pela inspeção da turgência da pele, ausência de saliva e umidade das mucosas, uma vez que a palpação dos tecidos não contribui para identificar sinais como edema intersticial;","o reflexo de Babinski deve ser pesquisado em pacientes com suspeita de lesão neurológica central, e sua presença em adultos é considerada normal quando o estímulo plantar provoca dorsiflexão do hálux e abertura dos dedos do pé;","na verificação da pressão arterial, é crucial que o manguito seja posicionado acima da fossa antecubital, e que seja inflado rapidamente até ultrapassar 10 a 20 mmHg o nível estimado da PA sistólica;","na palpação da tireoide, o exame deve ser realizado tanto por abordagem posterior quanto anterior. O exame consiste em identificar sua mobilidade durante a deglutição e textura. A presença de um nódulo fixo e não doloroso pode sugerir malignidade;","a avaliação pulmonar por meio da ausc ulta utiliza principalmente o diafragma do estetoscópio para detectar ruídos adventícios como estertores e sibilos, mas sopros cavernosos são avaliados preferencialmente com o uso da campânula"],"correta":"D"},{"numero":46,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"Durante a assistência a um paciente adulto do sexo masculi no, verificou-se que ele apresentava picos de febre em alguns horários do dia intercalados com temperaturas normais. Essa oscilação da temperatura é denominada febre:","alternativas":["sustentada;","remitente;","reincidente.","ondulante;","intermitente"],"correta":"E"},{"numero":47,"disciplina":"Enfermagem","assunto":"Saúde do Idoso","enunciado":"Uma paciente de 72 anos, com histórico de hipertensão arterial e insuficiência cardíaca, é admitida na unidade de emergência com queixa de dispneia ao esforço físico e mal -estar. Durante a admissão, foram registradas: frequência cardíaca (FC) = 112 bpm, irregular; frequência respiratória (FR) = 28 irpm; e saturação de oxigênio = 89% em ar ambiente. Acerca desses valores, é correto afirmar que:","alternativas":["os valores estão dentro da normalidade, pois a FC em idosos pode variar entre 60 e 120 bpm, e a FR entre 12 e 25 rpm;","a FR e a SpO2 estão dentro da normalidade, mas deve -se iniciar oxigenoterapia devido à queixa respiratória;","a saturação de oxigênio de 89% em ar ambiente é adequada para uma paciente idosa com insuficiência cardíaca, não sendo necessária suplementação de oxigênio;","a FR aumentada associada à hipoxemia é indicativa de comprometimento respiratório;","a FC de 112 bpm e a FR de 28 irpm estão dentro dos parâmetros normais para uma paciente idosa com insuficiência cardíaca"],"correta":"D"},{"numero":48,"disciplina":"Enfermagem","assunto":"Fundamentos e Semiotécnica","enunciado":"As medidas an tropométricas são ferramentas fundamentais na avaliação do estado nutricional do paciente, permitindo o monitoramento de riscos à saúde e intervenções terapêuticas. Nesse sentido, é correto afirmar que:","alternativas":["a altura é medida em pacientes acamados utilizando a extensão do braço dominante, sendo considerado um valor confiável por se correlacionar diretamente com a estatura de pacientes sem deformidades ósseas ou alterações musculoesqueléticas;","a circunferência da cintura deve ser aferida no ponto mais estreito entre as últimas costelas e a crista ilíaca, sendo um indicador independente do risco cardiometabólico, especialmente quando maior que 102 cm em homens ou 88 cm em mulheres;","o índice de massa corporal (IMC) é inadequado para avaliar obesidade em idosos, pois superestima a gordura corporal nessa população. Portanto, índices alternativos, como a razão cintura-quadril (RCQ), são mais apropriados em pacientes acima de 65 anos;","a avaliação do perímetro do braço é realizada no terço médio do braço direito, independentemente da lateralidade, e reflete diretamente as reservas musculares e gordurosas do indivíduo, sendo útil em pacientes gravemente enfermos;","a dobra cutânea subescapular é medida com o paciente em decúbito dorsal, para reduz ir interferências musculares. Essa medida é mais relevante para crianças e adolescentes devido ao crescimento acelerado e à necessidade de avaliação precoce de reservas adiposas."],"correta":"B"},{"numero":50,"disciplina":"Enfermagem","assunto":"Administração de Medicamentos e Cálculos","enunciado":"Um profissional de enfermagem está preparando a bomba de infusão para adm inistrar um medicamento em um paciente crítico. Sobre as funcionalidades desse equipamento, é correto afirmar que:","alternativas":["a bomba de infusão permite apenas a administração contínua de fluidos, não sendo possível programar infusões intermitentes ou em bolus;","o mecanismo de alarme da bomba de infusão indica apenas o término da infusão, sem detectar oclusões na linha ou falhas no fluxo do medicamento;","a taxa de infusão de uma bomba volumétrica permanece constante em todos os casos, sem possibilidade de aj uste conforme as necessidades clínicas do paciente;","a função \"modo PCA\" (controle da dor pelo paciente) permite que o paciente controle a administração de analgésicos, mas não limita a dose total administrada em um período determinado;","algumas bombas de infusão possuem controle por dosagem, permitindo calcular automaticamente a taxa de infusão com base na concentração do medicamento e na prescrição médica"],"correta":"E"},{"numero":51,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Uma paciente de 55 anos, em tratamento de leucemia mieloide aguda, apresenta quadro de infecção grave e foi prescrito anfotericina B lipossomal para tratamento de uma infecção fúngica. A prescrição orienta uma dose de 3 mg/kg/dia, administrada via infusão intravenosa em 6 horas. Sabendo-se que a anfotericina B lipossomal é um medicamento de alta vigilância, que deve ser diluído em solução adequada e administrado com cuidados específicos, a recomendação correta sobre o preparo e a administração segura desse medicamento é a seguinte:","alternativas":["a anfotericina B lipossomal deve ser diluída em solução de glicose 5% e administrada com equipo protegido da luz, devido à fotossensibilidade do fármaco;","a anfotericina B lipossomal pode ser diluída em soro fisiológico 0,9 % ou glicose 5%, desde que administrada imediatamente para evitar sua degradação;","não é necessário proteger a solução da luz, pois a formulação lipossomal reduz o risco de instabilidade;","deve ser utilizado um filtro específico no equipo para evitar embolia causada por partículas da solução;","a formulação lipossomal permite que esse medicamento seja administrado diretamente sem diluição"],"correta":"A"},{"numero":52,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Na assistência a uma criança em parada cardiorrespiratória (PCR), se houver pulso palpável de 60 batimentos por minuto ou mais, mas a respiração estiver ausente ou inadequada, a ventilação de resgate deve ser realizada da seguinte maneira:","alternativas":["10 a 20 ventilações de resgate por minuto;","20 a 30 ventilações de resgate por minuto;","30 a 40 ventilações de resgate por minuto;","1 ventilação de resgate a cada 4 ou 6 segundos;","1 ventilação de resgate a cada 6 ou 8 segundos"],"correta":"B"},{"numero":53,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um paciente de 68 anos com DPOC em estágio avançado encontra-se internado devido a uma exacerbação aguda, apresentando saturação d e oxigênio (SpO₂) de 86%, dispneia intensa e sinais clínicos de hipoxemia. Durante a avaliação, é prescrita a oxigenoterapia, objetivando a saturação adequada para esse caso. Nesse sentido, a alternativa que apresenta o dispositivo de oxigenação mais adequ ado, considerando o quadro clínico do paciente, é:","alternativas":["máscara de Venturi com fluxo ajustado para manter uma SpO₂ de 88-92%, evitando hiperóxia e retenção de CO₂;","cateter nasal de alto fluxo a 8 L/min, com umidificação, priorizando o conforto e evitando hipóxia;","máscara não reinalante a 10 L/min, visando à saturação > 94% rapidamente, para evitar evolução da hipóxia;","máscara facial simples a 6 L/min, como abordagem inicial, priorizando fácil aplicação e saturação > 96%;","cateter nasal comum a 2 L/min, mantendo monitorização periódica da SpO₂ e ajustando apenas em caso de piora."],"correta":"A"},{"numero":54,"disciplina":"Enfermagem","assunto":"Centro de Material e Esterilização (CME)","enunciado":"O técnico de enfermagem de uma unidade de pronto atendimento está organizando alguns materiais para limpeza e processamento. Entre eles, estão pinças hemostáticas, pinças de biópsia, pinças laparoscópicas canuladas, cânulas orotraqueais e termômetros digitais. Com base nos princípios de Spaulding e nas disposições da Anvisa acerca do processamento de produtos para a saúde, é correto afirmar que:","alternativas":["as pinças hemostáticas são artigos semicríticos e devem ser submetidas à desinfecção de alto nível antes do uso;","as pinças de biópsia são artigos críticos de conformação complexa, devendo ser esterilizadas por óxido de etileno;","as cânulas orotraqueais são artigos não críticos, devendo ser higienizadas com detergente enzimático antes do uso;","os termômetros digitais são artigos semicríticos e exigem desinfecção de nível intermediário após o uso para evitar contaminação cruzada;","as pinças laparosc ópicas devem passar pela lavadora ultrassônica com conector para canulados e que utilize tecnologia de fluxo intermitente"],"correta":"E"},{"numero":55,"disciplina":"Enfermagem","assunto":"Centro de Material e Esterilização (CME)","enunciado":"Uma unidade de saúde está revisando os protocolos de processamento de materiais para garantir maior segurança. A equipe está analisando os métodos de desinfecção e esterilização em diferentes situações clínicas, considerando fatores como tipo de material, resistência microbiana e custo-benefício. Com base nas técnicas de desinfecção e esterilização, é correto afirmar que:","alternativas":["o ácid o peracético tem ação rápida, baixa toxicidade e é biodegradável, sendo um método apropriado e de baixo custo para o processamento de instrumentais cirúrgicos;","o peróxido de hidrogênio, em concentrações de 3% e 6%, tem ação rápida, é biodegradável e at óxico, mas é contraindicado para capilares hemodialisadores e lentes de contato;","o calor úmido provoca a desnaturação e coagulação das proteínas e a fluidificação dos lipídios, sendo amplamente utilizado nos serviços de saúde;","o plasma de peróxido de hidrogênio é recomendado para materiais críticos metálicos, mas não é eficaz contra esporos bacterianos;","o óxido de etileno é um gás vastamente utilizado na esterilização de materiais médico -hospitalares, pois, além de eficiente, tem baixa toxicidade e não agride o meio ambiente"],"correta":"C"},{"numero":56,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Uma unidade de internação identificou um aumento de casos de infecção por Klebsiella pneumoniae produtora de carbapenemase (KPC). A Comissão de Controle de Infecção Hospitalar (CCIH) do hospital está implementando medidas preventivas para conter a disseminação desse patógeno multirresistente. Com base nas recomendações da Anvisa para a prevenção de infecção relacionada à assistência à saúde (IRAS) e controle de microrganismos multirresistentes, a alter nativa que corresponde à medida de prevenção adequada é:","alternativas":["isolamento respiratório do paciente e uso de máscara N95 para todos os profissionais durante o atendimento direto;","uso de precauções padrão associadas às precauções de contato, incluindo avental e luvas, e priorização da higiene das mãos;","uso de desinfetantes de baixo nível para limpeza de superfícies ao redor do leito, associado ao descarte regular de resíduos contaminados;","transferência imediata do paciente para uma uni dade de isolamento, mantendo as precauções por gotículas para os profissionais de saúde e acompanhantes;","uso de antimicrobianos profiláticos para todos os pacientes da unidade e filtro HEPA nas enfermarias para prevenir novas colonizações por KPC"],"correta":"B"},{"numero":57,"disciplina":"Enfermagem","assunto":"Controle de Infecção e Biossegurança","enunciado":"Com base nas recomendações da Anvisa, em relação às medidas de prevenção de infecção do trato urinário (ITU), é correto afirmar que:","alternativas":["a troca sistemática das sondas vesicais de demora a cada cinco dias reduz a incidência de ITU e deve ser adotada na rotina assistencial;","a lavagem frequente do meato urinário com antissépticos antes da coleta de urina garante a prevenção de ITU associada ao cateterismo;","a técnica asséptica na inserção do cateter e a manutenção do sistema fechado estão entre as pri ncipais medidas para prevenir ITU;","o uso profilático de antibióticos antes do cateterismo vesical em todos os pacientes reduz a colonização bacteriana e previne ITU;","a instalação de um sistema de drenagem com irrigação contínua em todos os pacientes previne ITU ao reduzir o risco de estase urinária."],"correta":"C"},{"numero":58,"disciplina":"Enfermagem","assunto":"Saúde Mental","enunciado":"Durante a admissão de um paciente em uma unidade de saúde mental, foi identificado comportamento agitado, aumento de energia (com diminuição da necessidade de sono), pressão de fala e taquilalia, irr itabilidade, paranoia e impulsividade, que impactavam negativamente a interação social do paciente. Considerando esses achados, é correto afirmar que:","alternativas":["o quadro é sugestivo de esquizofrenia, e a equipe deve promover atividades em grupo para favorecer a socialização e reduzir a agitação;","o quadro indica transtorno de ansiedade generalizada, exigindo estratégias não farmacológicas para controle de crises, como técnicas de respiração profunda;","o quadro é característico de episódio maníaco do transto rno afetivo bipolar e requer atenção para prevenir comportamentos impulsivos e manter a segurança;","são manifestações características do transtorno depressivo maior, sendo prioritário um ambiente calmo com reforço à comunicação empática e estímulo gradual à interação;","o quadro está relacionado ao transtorno obsessivo - compulsivo (TOC), e a equipe deve reforçar o uso de rotinas predefinidas e evitar mudanças inesperadas para reduzir a agitação"],"correta":"C"},{"numero":59,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Com base nas disposições do Ministério da Saúde acerca do aleitamento materno, suas vantagens e contraindicações, analise as afirmativas a seguir, considerando V para a(s) verdadeira(s) e F para a(s) falsa(s). ( ) O colostro, nos primeiros dois a três dias de vida, é suficiente para nutrir e hidratar recém-nascidos saudáveis, não sendo necessário qualquer outro líquido além do leite materno, pois eles nascem com níveis de hidratação tecidual relativamente altos. ( ) A amamentação oferece diversos benefícios à mulher, como a redução dos riscos de he morragia no pós -parto e das chances de desenvolver câncer de mama, ovários e colo do útero no futuro. ( ) Entre as contraindicações permanentes para a amamentação estão mães portadoras do vírus HIV, HTLV -1 e HTLV-2 e entre as contraindicações temporária s estão mulheres com câncer de mama que foi tratado ou está em tratamento. A sequência correta é:","alternativas":["F – V – F;","V – V – V;","F – F – F;","V – V – F;","F – V – V"],"correta":"D"},{"numero":60,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"Em novembro de 2024, foi adotado pelo Ministério da Saúde um novo esquema vacinal contra a poliomielite. Acerca dessas mudanças, é correto afirmar que:","alternativas":["a vacina oral poliomielite bivalente (VOPb) foi excluída do esquema principal e fará parte somente dos reforços;","o novo esquema contempla 3 doses e um reforço da vacina inativada poliomielite (VIP);","o intervalo mínimo entre as doses da vacina inativada poliomielite (VIP) deve ser de 60 dias;","a primeira dose deve ser com a vacina oral poliomielite bivalente (VOPb) e as demais doses com a vacina inativada poliomielite (VIP);","a segunda dose da vacina inativada poliomielite (VIP) deve ser administrada aos 6 meses de idade"],"correta":"B"},{"numero":61,"disciplina":"Enfermagem","assunto":"Imunização","enunciado":"Considerando as recomendações do Ministério da Saúde acerca do armazenamento de imunobiológicos nas câmaras refrigeradas, é correto afirmar que:","alternativas":["as vacinas devem ser armazenadas na prateleira superior, enquanto os diluentes podem ser acondicionados na porta da câmara refrigerada, pois não são sensíveis a variações de temperatura;","os imunobiológicos na sala de vacinação devem ser mantid os à temperatura entre +2°C e +8°C, sendo a temperatura de controle ideal +5°C;","as vacinas com e sem diluente podem ser armazenadas na mesma prateleira, desde que a câmara não seja sobrecarregada, permitindo boa circulação de ar frio;","é permitido o uso do compartimento do congelador para armazenar vacinas do tipo liofilizada, pois estas devem ser mantidas abaixo de 0°C até o momento de sua reconstituição;","os diluentes devem ser armazenados em temperatura ambiente e resfriados apenas no momento d a aplicação, pois a refrigeração prévia pode comprometer sua estabilidade"],"correta":"B"},{"numero":62,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um paciente adulto de 65 anos sofreu parada cardiorrespiratória (PCR) durante o atendimento em uma unidade de saúde. A ressuscitação cardiopulmonar (RCP) foi iniciada com compressões torácicas e ventilações mecânicas, e a monitorização indicou ritmo chocável. Nesse caso, a correta sequência das ações é:","alternativas":["realizar a desfibrilação imediatamente com 250 Joules (bifásico) ou 360 Joules (monofásico), continuar a RCP por 2 minutos, e administrar 1 mg de adrenalina intravenosa após o primeiro ciclo de RCP;","realizar a desfibrilação imediatamente com 200 Joules, continuar a RCP por 4 minutos, e administrar 300 mg de amiodarona após o segundo choque;","realizar a desfibrilaçã o imediatamente com 120 -200 Joules (bifásico) ou 360 Joules (monofásico), continuar a RCP por 2 minutos, e administrar 1 mg de adrenalina intravenosa após o segundo ciclo de RCP;","realizar a desfibrilação imediatamente com 120 -200 Joules (bifásico) ou 3 60 Joules (monofásico), continuar a RCP por 4 minutos, e administrar 300 mg de amiodarona após o terceiro choque;","realizar a desfibrilação imediatamente com 120 -200 Joules (bifásico) ou 360 Joules (monofásico), continuar a RCP por 2 minutos, e administrar 1 mg de adrenalina intravenosa após o primeiro ciclo de RCP."],"correta":"C"},{"numero":63,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Um paciente adulto deu entrada na unidade de pronto atendimento com sinais e sintomas de hipotermia grave (< 28°C). Um desses sintomas é:","alternativas":["palidez;","calafrio;","inconsciência;","tremor incontrolável;","diminuição da capacidade de resposta"],"correta":"C"},{"numero":64,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Durante uma consulta de rotina, uma mulher foi orientada acerca das contraindicações relacionadas à terapia hormonal na menopausa. Entre essas contraindicações, está:","alternativas":["hiperlipidemia;","diabetes mellitus;","miomatose uterina;","síndrome metabólica;","doença hepática aguda"],"correta":"E"},{"numero":65,"disciplina":"Enfermagem","assunto":"Diabetes Mellitus","enunciado":"Um paciente adulto, sexo masculino, teve pré -diabetes confirmada em uma investigação inicial. De acordo com as diretrizes da Sociedade Brasileira de Diabetes, a frequência recomendada para repetição do rastreamento de DM2 desse paciente é:","alternativas":["a cada ano;","a cada dois anos;","a cada três anos;","a cada três meses;","a cada seis meses"],"correta":"A"},{"numero":66,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"Um paciente adulto, com suspeita de dengue, apresentou sinais e sintomas característicos do Grupo C, sendo um desses sintomas:","alternativas":["mialgia;","exantema;","taquicardia;","sangramento de mucosa;","enchimento capilar lento"],"correta":"D"},{"numero":67,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"Na realização da prova do laço em um paciente adulto com suspeita de dengue, o resultado é considerado positivo se houver:","alternativas":["5 ou mais petéquias no quadrado com 2,5 cm desenhado no antebraço;","10 ou mais petéquias no quadrado com 3,5 cm desenhado no antebraço;","15 ou mais petéquias no quadrado com 3,5 cm de senhado no antebraço;","20 ou mais petéquias no quadrado com 2,5 cm desenhado no antebraço;","25 ou mais petéquias no quadrado com 3,5 cm desenhado no antebraço"],"correta":"D"},{"numero":68,"disciplina":"Enfermagem","assunto":"Tuberculose","enunciado":"Um paciente em tratamento de tuberculose com o esquema básico começou a apresentar cri ses convulsivas e sintomas de psicose. Esses são sinais de efeitos adversos provocados pelo seguinte fármaco:","alternativas":["etambutol;","isoniazida;","rifampicina;","pirazinamida;","estreptomicina"],"correta":"B"},{"numero":69,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Considerando as disposições do Ministério da Saúde acerca do câncer do colo do útero, é correto afirmar que:","alternativas":["as consultas de acompanhamento devem ocorrer a cada seis meses nos primeiros dois anos após o término do tratamento;","os principais sintomas do câncer do colo do útero são dor pélvica e alterações urinárias;","o método de rastreamento deve ser oferecido às mulheres ou qualquer pessoa com colo do útero, na faixa etária de 20 a 55 anos;","a vacina papilomavírus humano recombinante é contraindicada para pessoas portadoras de HIV;","o uso de contraceptivos orais é um dos fatores de risco para o desenvolvimento de câncer do colo do útero"],"correta":"E"},{"numero":70,"disciplina":"Enfermagem","assunto":"Saúde da Mulher","enunciado":"Com base na Diretriz Nacional de Assistência ao Parto Normal, é correto afirmar que:","alternativas":["a massagem uterina sustentada é recomendada como intervenção par a prevenir HPP em mulheres que receberam ocitocina profilática;","a fase latente do primeiro período do parto é caracterizada por contrações uterinas dolorosas, regulares, e um grau substancial de apagamento cervical, em nulíparas e multíparas;","a cardiotocografia de rotina é recomendada para a avaliação do bem -estar fetal na admissão do parto de início espontâneo, em gestantes saudáveis de risco habitual;","em parturientes de risco habitual, deve -se verificar a frequência cardíaca materna de 1 em 1 hora e a frequência cardíaca fetal a cada 30 minutos;","o exame pélvico digital é contraindicado na fase ativa do primeiro estágio do trabalho de parto em parturientes de risco habitual."],"correta":"D"},{"numero":71,"disciplina":"Enfermagem","assunto":"Saúde da Criança e do Adolescente","enunciado":"Durante a assistência a um recém -nascido, foi avaliado o desenvolvimento neuropsicomotor, por meio da verificação dos reflexos primitivos. Acerca desses reflexos, é correto afirmar que:","alternativas":["o reflexo de Moro é considerado ausente quando o recém - nascido estende os membros superiores ao som de um estímulo abrupto;","o reflexo de preensão palmar persiste por toda a infância e está relacionado à adaptação funcional da criança;","a ausência do reflexo de sucção pode ser um sinal indicativo de disfunção neurológica grave e requer avaliação imediata;","o reflexo tônico cervical assimétrico deve persistir até aproximadamente o 6º mês de vida, indicando que o tônus muscular está se desenvolvendo adequadamente;","o reflexo de marcha automática não tem relação com o desenvolvimento neurológico da criança e pode esta r ausente sem significar uma alteração"],"correta":"C"},{"numero":72,"disciplina":"Enfermagem","assunto":"Urgência e Emergência","enunciado":"Uma mulher de 28 anos buscou atendimento em uma unidade básica de saúde relatando ausência de menstruação há dois meses, acompanhada de náuseas e sensibilidade mamária. Durante o exame físico, foi verificado úter o aumentado à palpação, tubérculos de Montgomery e sinal de Hegar. Em relação ao diagnóstico de gravidez, de acordo com os protocolos do Ministério da Saúde, as manifestações clínicas apresentadas pela paciente e os achados do exame físico correspondem, respectivamente, a sinais de:","alternativas":["presunção, presunção, presunção, probabilidade, presunção e probabilidade;","probabilidade, presunção, presunção, probabilidade, certeza e probabilidade;","presunção, probabilidade, presunção, certeza, presunção e probabilidade;","certeza, presunção, presunção, probabilidade, presunção e probabilidade;","probabilidade, probabilidade, presunção, probabilidade e presunção e presunção"],"correta":"A"},{"numero":73,"disciplina":"Enfermagem","assunto":"Saúde do Trabalhador","enunciado":"Em um hospital geral, uma enfermeira se feriu acidentalmente com uma agulha contam inada após administrar medicação intravenosa em um paciente com sorologia desconhecida. De acordo com os protocolos do Ministério da Saúde relacionados à segurança no trabalho, a conduta correta é:","alternativas":["lavar a área do ferimento com álcool a 70% e aplicar c urativo oclusivo, seguindo para avaliação clínica em até 48 horas;","esfregar vigorosamente o local do acidente para reduzir o risco de infecção e comunicar o serviço de saúde no final do plantão;","lavar o local com água e sabão, comunicar imediatamen te o setor de saúde ocupacional do hospital e iniciar o protocolo de profilaxia pós-exposição (PEP), se indicado;","envolver a área lesada com um curativo compressivo e encaminhar para atendimento especializado somente se os exames laboratoriais do paciente confirmarem infecção;","ignorar a exposição inicial se não houver sangramento visível e iniciar a PEP imediatamente, caso haja sangramento ou lesão aparente"],"correta":"C"},{"numero":74,"disciplina":"Legislação do COFEN","assunto":"Código de Ética dos Profissionais de Enfermagem","enunciado":"Um profissional de enfermagem revelou informações sigilosas acerca do estado de saúde de um paciente, sem o seu consentimento. Considerando as disposições do Código de Ética dos Profissionais de Enfermagem acerca dessa conduta, analise as afirmativas a seguir, considerando V para a(s) verdadeira(s) e F para a(s) falsa(s). ( ) A vio lação do sigilo profissional configura falta ética, cuja punição é responsabilidade exclusiva do Conselho Federal de Enfermagem. ( ) O sigilo é um dever do profissional, e a divulgação de informações sobre o paciente sem o seu consentimento caracteriza infração ética sujeita a penalidades que podem incluir advertência, suspensão ou censura. ( ) De acordo com as disposições do Código de Ética, o profissional deve ser imediatamente afastado das atividades profissionais até que a penalidade seja aplicada pelo Conselho correspondente. A sequência correta é:","alternativas":["F – V – V;","V – V – V;","F – F – F;","V – F – V;","F – V – F"],"correta":"E"},{"numero":76,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"As hepatites virais são infecções causadas por diferentes agentes virais (A, B, C, D e E), que atingem o fígado, causando alterações leves, moderadas ou graves. Com base nos diversos modos de transmissão, manifestações clínicas e estratégias de prevenção, é correto afirmar que:","alternativas":["a hepatite A pode ser transmitida pela ingestão de carne mal cozida ou produtos derivados de an imais infectados e de forma vertical, de uma mulher grávida para seu bebê;","a infecção pelo vírus da hepatite B (HBV) pode evoluir para a forma crônica em adultos em até 90% dos casos, sendo considerada rara em neonatos;","a hepatite C é frequentement e assintomática na fase inicial, mas apresenta um alto índice de cronicidade, com o principal mecanismo de transmissão ocorrendo por meio de contato com sangue contaminado;","não existe vacina específica contra o vírus da hepatite D, sendo recomendada a vacina contra a hepatite A como estratégia preventiva para coinfecções;","a hepatite E possui maior impacto em populações com acesso precário à água potável, sendo associada principalmente ao contato com fluidos corporais infectados em áreas endêmicas"],"correta":"C"},{"numero":77,"disciplina":"Enfermagem","assunto":"Saúde do Adulto","enunciado":"Os métodos diagnósticos não invasivos são fundamentais para a avaliação funcional do sistema cardiovascular, permitindo um diagnóstico mais seguro e preciso. Sobre os procedimentos não invasivos de análise funcional cardiovascular, é correto afirmar que:","alternativas":["o ecocardiograma com estresse farmacológico utiliza medicamentos como o metoprolol para aumentar a frequência cardíaca, facilitando a avaliação de isquemia miocárdica;","o teste de esforço é indicado para pacientes com probabilidade intermediária d e doença arterial coronariana, avaliando alterações eletrocardiográficas e a resposta hemodinâmica durante o esforço físico controlado;","a ressonância magnética cardíaca é uma ferramenta confiável para avaliar fibrose miocárdica, mas é pouco precisa na avaliação da função ventricular, sendo contraindicada em pacientes com qualquer dispositivo metálico;","a cintilografia miocárdica de perfusão, apesar de não ser invasiva, não é indicada para pacientes com contraindicação ao uso de contrastes, uma vez qu e o método depende exclusivamente de agentes iodados;","a angiografia por tomografia computadorizada (angio -TC) cardíaca é restrita ao estudo anatômico das coronárias, não sendo capaz de fornecer informações funcionais, como a avaliação do fluxo coronariano"],"correta":"B"},{"numero":78,"disciplina":"Enfermagem","assunto":"Epidemiologia e Vigilância em Saúde","enunciado":"A notificação compulsória de doenças, agravos e eventos de saúde pública é uma importante estratégia de vigilância no Sistema Único de Saúde. Com base nas disposições do Ministério da Saúde a esse respeito, é correto afirmar que:","alternativas":["apenas os pro fissionais de saúde que atuam em serviços públicos de saúde estão obrigados a notificar doenças e agravos de notificação compulsória, sendo opcional para aqueles que atuam na rede privada;","a notificação compulsória imediata deve ser realizada em até 24 horas, exclusivamente por unidades de atenção básica, sendo os hospitais isentos dessa obrigatoriedade;","doenças como tuberculose e hanseníase, por sua prevalência e impacto na saúde pública, estão incluídas na lista de notificação compulsória regular em todo o território nacional;","os agravos relacionados ao trabalho, como acidente com exposição a materiais biológicos, não fazem parte das condições de notificação compulsória, pois são de responsabilidade exclusiva dos serviços de segurança do trabalho das unidades de saúde;","a atualização da lista de notificação compulsória ocorre apenas com novas doenças emergentes, como as síndromes respiratórias causadas por vírus recentemente identificados, sendo fixada como medida excepcional e temporária"],"correta":"C"},{"numero":79,"disciplina":"Enfermagem","assunto":"Arboviroses (Dengue, Zika, Chikungunya, Febre Amarela, Oropouche e Nilo Ocidental)","enunciado":"Uma gestante de 30 anos, na 28ª semana de gestação, foi encaminhada à unidade de saúde com sintomas suspeitos de infecção pelo vírus Zika. Nesse caso, com base nas disposições acerca da notificação compulsória de doenças e agravos, a notificação deve ser realizada:","alternativas":["em até sete dias;","em até 24 horas;","somente após a confirmação diagnóstica;","prioritariamente em unidades sentinelas;","obrigatoriamente pelo médico assistente"],"correta":"B"},{"numero":80,"disciplina":"Enfermagem","assunto":"Segurança do Paciente","enunciado":"O Programa Nacional de Segurança do Pacien te (PNSP), instituído pelo Ministério da Saúde, tem como objetivo reduzir a ocorrência de incidentes relacionados à assistência à saúde. Considerando os protocolos de segurança já estabelecidos pelo PNSP, a estratégia mais adequada de prevenção de erros de medicação na rotina assistencial é:","alternativas":["implementar a dupla checagem de medicamentos de alta vigilância por dois profissionais de saúde antes da administração, garantindo a confirmação da dose, via e horário corretos;","priorizar a prescrição eletrônica sem a necessidade de revisão manual, pois sistemas informatizados eliminam o risco de erros de medicação;","estabelecer um sistema de gestão de riscos que inclua a análise de causas raízes de eventos adversos e a capacitação contínua da equipe assistencial;","utilizar tecnologias como códigos de barras para a identificação de medicamentos e pacientes, associadas à integração com sistemas de prescrição eletrônica;","promover a cultura de segurança do paciente por meio da notificação não punitiva de ev entos adversos, incentivando a aprendizagem organizacional e a melhoria contínua dos processos assistenciais. RASCUNHO PROVA DISCURSIVA Os sociólogos explicam certas atitudes dos cidadãos contemporâneos, como a recusa do trabalho ou a recusa de ter filhos, pelo temor de dias futuros bastante incertos. Entre as causas de uma possível angústia diante do futuro, qual ou quais delas o(a) incomoda(m) mais? Exponha suas opiniões sobre o tema, indicando razões objetivas para os seus posicionamentos, elaborando um texto dissertativo-argumentativo, em linguagem culta, com no mínimo 20 e no máximo 30 linhas. Valor: 40 pontos. 1 5 10 15 20 25 30"],"correta":"A"}]}] as const;
export async function sincronizarFGVMPU2025Enfermagem(){
 const user=await prisma.usuario.findFirst({orderBy:{id:"asc"},select:{id:true}});
 if(!user)return {inseridas:0,existentes:0,repetidas:0};
 const norm=(s:string)=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
 const atuais=await prisma.questao.findMany({where:{fonte:FONTE_PROVAS_REAIS},select:{enunciado:true}});
 const hashes=new Set(atuais.map(q=>norm(q.enunciado))),disciplinas=new Map<string,number>();
 let inseridas=0,existentes=0,repetidas=0;
 for(const lote of LOTES)for(const q of lote.questoes){
  const origemId="fgv-"+lote.codigo+"-tipo1-q"+String(q.numero).padStart(2,"0");
  if(!q.enunciado.trim()||q.alternativas.length!==5||q.alternativas.some(a=>!a.trim())||
      !["A","B","C","D","E"].includes(q.correta)||new Set(q.alternativas.map(a=>a.toLowerCase().trim())).size!==5)
      throw new Error("[mpu-2025-enfermagem] Item inválido "+origemId);
  if(await prisma.questao.findFirst({where:{fonte:FONTE_PROVAS_REAIS,origemId},select:{id:true}})){existentes++;continue;}
  const key=norm(q.enunciado);if(hashes.has(key)){repetidas++;continue;}
  let disciplinaId=disciplinas.get(q.disciplina);
  if(!disciplinaId){
   let d=await prisma.disciplina.findFirst({where:{usuarioId:user.id,nome:{equals:q.disciplina,mode:"insensitive"}},select:{id:true}});
   if(!d)d=await prisma.disciplina.create({data:{usuarioId:user.id,nome:q.disciplina},select:{id:true}});
   disciplinaId=d.id;disciplinas.set(q.disciplina,disciplinaId);
  }
  await prisma.questao.create({data:{
    usuarioId:user.id,disciplinaId,fonte:FONTE_PROVAS_REAIS,origemId,
    enunciado:q.enunciado,tema:q.assunto,dificuldade:"medio",banca:"FGV",
    orgao:lote.orgao,ano:lote.ano,cargo:lote.cargo,fonteUrl:lote.prova,
    explicacao:"FGV/MPU 2025, "+lote.cargo+", prova Tipo 1, questão "+q.numero+
    ". Gabarito definitivo: alternativa "+q.correta+". Caderno: "+lote.prova+" | Gabarito: "+lote.gabarito,
    alternativas:{create:q.alternativas.map((texto,i)=>({texto:"ABCDE"[i]+") "+texto,correta:"ABCDE"[i]===q.correta}))}
  }});
  hashes.add(key);inseridas++;
 }
 console.log("[mpu-2025-enfermagem] "+inseridas+" inseridas; "+existentes+" existentes; "+repetidas+" repetidas ignoradas.");
 return {inseridas,existentes,repetidas};
}
